browser-use <<'PY'
# Get more detailed info about the first story and its score
result = js("""
const items = document.querySelectorAll('.athing');
if (items.length > 0) {
    const firstItem = items[0];
    const titleElement = firstItem.querySelector('.titleline a');
    const title = titleElement ? titleElement.textContent : 'N/A';

    // The score is typically in the subtext row
    const nextRow = firstItem.nextElementSibling;
    if (nextRow) {
        const subtext = nextRow.querySelector('.subtext');
        if (subtext) {
            // Look for span with class 'score' or text containing 'points'
            const spans = subtext.querySelectorAll('span');
            let points = 'N/A';
            for (const span of spans) {
                if (span.className === 'score' || span.textContent.includes('point')) {
                    points = span.textContent.trim();
                    break;
                }
            }
            return { title: title, points: points, subtextHTML: subtext.innerHTML };
        }
    }
}
return { title: 'Not found', points: 'N/A' };
""")
print(result)
